            stack=[p]; comp=set()
            while stack:
                q=stack.pop()
                if q in comp: continue
                comp.add(q)
                if conn4: nbrs=[(q[0]+1,q[1]),(q[0]-1,q[1]),(q[0],q[1]+1),(q[0],q[1]-1)]
                else: nbrs=[(q[0]+dr,q[1]+dc) for dr in(-1,0,1) for dc in(-1,0,1) if (dr,dc)!=(0,0)]
                for n in nbrs:
                    if n in cells and n not in comp: stack.append(n)
