def nn_tour(pts):
    pts=list(pts); start=pts[0]; tour=[start]; rem=[p for p in pts[1:]]
    cur=start
    while rem:
        nxt=min(rem,key=lambda p:(p[0]-cur[0])**2+(p[1]-cur[1])**2)
        tour.append(nxt); rem.remove(nxt); cur=nxt
    return tour
def inside_poly(tour,Rr,Cc):
    # even-odd point in polygon for cell centers
    poly=[(c,r) for r,c in tour]  # x,y
    res={}
    n=len(poly)
    for r in range(Rr):
        for c in range(Cc):
            x,y=c+0.5,r+0.5
            inside=False
            j=n-1
            for i in range(n):
                xi,yi=poly[i]; xj,yj=poly[j]
                if (yi>y)!=(yj>y) and x < (xj-xi)*(y-yi)/(yj-yi)+xi:
                    inside=not inside
                j=i
            res[(r,c)]=inside
    return res
